using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "LunarSingularityOmenData", menuName = "Data/Battle/Omens System/Omen Data/Moonie/LunarSingularityOmenData")]
public class LunarSingularityOmenData : OmenData
{
	[Header("Lunar Singularity")]
	[SerializeField]
	private DiceTier hexDiceTier;

	public override void Initialize(OmenInstance omenInstance)
	{
		ReferenceSingleton<MoonieOmensHandler>.Instance.LunarSingularityOmenAction = (DiceInstance diceInstance) => (!(diceInstance.Dice.DiceTier == hexDiceTier)) ? 1 : ActionValue;
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<MoonieOmensHandler>.Instance.LunarSingularityOmenAction = null;
	}
}
